"""Bundle supabase/migrations/*.sql into supabase/setup-all.sql for pasting into the Supabase SQL Editor.

Usage:  python scripts/bundle-migrations.py
"""
import glob
import pathlib

files = sorted(glob.glob("supabase/migrations/*.sql"))
out = [
    "-- ALL MIGRATIONS IN ONE FILE — paste into Supabase → SQL Editor → Run.",
    "-- Generated by scripts/bundle-migrations.py from supabase/migrations/ (do not edit here).",
    "-- Run it once on an empty project.",
    "",
]
for f in files:
    out += [f"-- ===================== {pathlib.Path(f).as_posix()} =====================", open(f, encoding="utf-8").read(), ""]
pathlib.Path("supabase/setup-all.sql").write_text("\n".join(out), encoding="utf-8")
print(f"Bundled {len(files)} migrations into supabase/setup-all.sql")
